-- Generated by scripts/gen_tpch_cases.py: the TPC-H queries of bench/tpch/ (Spark SQL) over a small
-- synthetic data set, so the benchmark's query text is also checked against Spark 3.5.

-- @setup
CREATE OR REPLACE TEMPORARY VIEW region AS SELECT * FROM VALUES (0, 'AFRICA', 'region 0'), (1, 'AMERICA', 'region 1'), (2, 'ASIA', 'region 2'), (3, 'EUROPE', 'region 3'), (4, 'MIDDLE EAST', 'region 4') AS t(r_regionkey, r_name, r_comment);

-- @setup
CREATE OR REPLACE TEMPORARY VIEW nation AS SELECT * FROM VALUES (0, 'ALGERIA', 0, 'nation 0'), (1, 'ARGENTINA', 1, 'nation 1'), (2, 'BRAZIL', 1, 'nation 2'), (3, 'CANADA', 1, 'nation 3'), (4, 'EGYPT', 4, 'nation 4'), (5, 'ETHIOPIA', 0, 'nation 5'), (6, 'FRANCE', 3, 'nation 6'), (7, 'GERMANY', 3, 'nation 7'), (8, 'INDIA', 2, 'nation 8'), (9, 'INDONESIA', 2, 'nation 9'), (10, 'IRAN', 4, 'nation 10'), (11, 'IRAQ', 4, 'nation 11'), (12, 'JAPAN', 2, 'nation 12'), (13, 'JORDAN', 4, 'nation 13'), (14, 'KENYA', 0, 'nation 14'), (15, 'MOROCCO', 0, 'nation 15'), (16, 'MOZAMBIQUE', 0, 'nation 16'), (17, 'PERU', 1, 'nation 17'), (18, 'CHINA', 2, 'nation 18'), (19, 'ROMANIA', 3, 'nation 19'), (20, 'SAUDI ARABIA', 4, 'nation 20'), (21, 'VIETNAM', 2, 'nation 21'), (22, 'RUSSIA', 3, 'nation 22'), (23, 'UNITED KINGDOM', 3, 'nation 23'), (24, 'UNITED STATES', 1, 'nation 24') AS t(n_nationkey, n_name, n_regionkey, n_comment);

-- @setup
CREATE OR REPLACE TEMPORARY VIEW supplier AS SELECT
  CAST(id + 1 AS INT) AS s_suppkey, concat('Supplier#', lpad(CAST(id + 1 AS STRING), 9, '0')) AS s_name,
  concat('addr ', CAST(id AS STRING)) AS s_address, CAST(pmod(id * 7, 25) AS INT) AS s_nationkey,
  concat(CAST(10 + pmod(id * 7, 25) AS STRING), '-', lpad(CAST(id AS STRING), 3, '0'), '-555-0100') AS s_phone,
  CAST(pmod(id * 3779, 11000) / 1.0 - 999.99 AS DECIMAL(15,2)) AS s_acctbal,
  CASE WHEN pmod(id, 9) = 0 THEN 'careful Customer accounts Complaints' ELSE concat('supplier comment ', CAST(id AS STRING)) END AS s_comment
  FROM range(100);

-- @setup
CREATE OR REPLACE TEMPORARY VIEW part AS SELECT
  CAST(id + 1 AS INT) AS p_partkey,
  concat(element_at(array('almond', 'forest', 'green', 'blue', 'khaki', 'red', 'navy', 'pink', 'lemon', 'olive', 'plum'), CAST(pmod(id, 11) AS INT) + 1), ' ', element_at(array('almond', 'forest', 'green', 'blue', 'khaki', 'red', 'navy', 'pink', 'lemon', 'olive', 'plum'), CAST(pmod(id * 3 + 1, 11) AS INT) + 1), ' ', element_at(array('almond', 'forest', 'green', 'blue', 'khaki', 'red', 'navy', 'pink', 'lemon', 'olive', 'plum'), CAST(pmod(id * 7 + 2, 11) AS INT) + 1)) AS p_name,
  concat('Manufacturer#', CAST(pmod(id, 5) + 1 AS STRING)) AS p_mfgr,
  concat('Brand#', CAST(pmod(id, 5) + 1 AS STRING), CAST(pmod(id * 3, 5) + 1 AS STRING)) AS p_brand,
  concat(element_at(array('STANDARD', 'SMALL', 'MEDIUM', 'LARGE', 'ECONOMY', 'PROMO'), CAST(pmod(id, 6) AS INT) + 1), ' ', element_at(array('ANODIZED', 'BURNISHED', 'PLATED', 'POLISHED', 'BRUSHED'), CAST(pmod(id * 7, 5) AS INT) + 1), ' ', element_at(array('TIN', 'NICKEL', 'BRASS', 'STEEL', 'COPPER'), CAST(pmod(id * 3, 5) AS INT) + 1)) AS p_type,
  CAST(pmod(id * 13, 50) + 1 AS INT) AS p_size, element_at(array('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG', 'MED BAG', 'MED BOX', 'MED PKG', 'MED PACK', 'LG CASE', 'LG BOX', 'LG PACK', 'LG PKG', 'JUMBO BOX', 'WRAP CASE'), CAST(pmod(id * 5, 14) AS INT) + 1) AS p_container,
  CAST(900 + pmod(id, 1000) / 10.0 AS DECIMAL(15,2)) AS p_retailprice, concat('part comment ', CAST(id AS STRING)) AS p_comment
  FROM range(200);

-- @setup
CREATE OR REPLACE TEMPORARY VIEW partsupp AS SELECT
  CAST(pmod(id, 200) + 1 AS INT) AS ps_partkey,
  CAST(pmod(pmod(id, 200) + div(id, 200) * 25, 100) + 1 AS INT) AS ps_suppkey,
  CAST(pmod(id * 7919, 9999) + 1 AS INT) AS ps_availqty, CAST(1 + pmod(id * 104729, 100000) / 100.0 AS DECIMAL(15,2)) AS ps_supplycost,
  concat('partsupp comment ', CAST(id AS STRING)) AS ps_comment
  FROM range(800);

-- @setup
CREATE OR REPLACE TEMPORARY VIEW customer AS SELECT
  CAST(id + 1 AS INT) AS c_custkey, concat('Customer#', lpad(CAST(id + 1 AS STRING), 9, '0')) AS c_name,
  concat('caddr ', CAST(id AS STRING)) AS c_address, CAST(pmod(id * 11, 25) AS INT) AS c_nationkey,
  concat(CAST(10 + pmod(id * 11, 25) AS STRING), '-', lpad(CAST(id AS STRING), 3, '0'), '-555-0199') AS c_phone,
  CAST(pmod(id * 7907, 11000) / 1.0 - 999.99 AS DECIMAL(15,2)) AS c_acctbal, element_at(array('AUTOMOBILE', 'BUILDING', 'FURNITURE', 'MACHINERY', 'HOUSEHOLD'), CAST(pmod(id, 5) AS INT) + 1) AS c_mktsegment,
  concat('customer comment ', CAST(id AS STRING)) AS c_comment
  FROM range(300);

-- @setup
CREATE OR REPLACE TEMPORARY VIEW orders AS SELECT
  CAST(id + 1 AS INT) AS o_orderkey,
  CAST(3 * pmod(id * 7 + div(id, 97), 100) + 1 + pmod(div(id, 3), 2) AS INT) AS o_custkey,
  element_at(array('F', 'O', 'P'), CAST(pmod(id * 5, 3) AS INT) + 1) AS o_orderstatus, CAST(1000 + pmod(id * 7919, 400000) / 1.0 AS DECIMAL(15,2)) AS o_totalprice,
  date_add(DATE '1992-01-01', CAST(pmod(id * 13, 2400) AS INT)) AS o_orderdate, element_at(array('1-URGENT', '2-HIGH', '3-MEDIUM', '4-NOT SPECIFIED', '5-LOW'), CAST(pmod(id * 3, 5) AS INT) + 1) AS o_orderpriority,
  concat('Clerk#', lpad(CAST(pmod(id, 50) AS STRING), 9, '0')) AS o_clerk, 0 AS o_shippriority,
  CASE WHEN pmod(id, 13) = 0 THEN 'quick special packages requests sleep' ELSE concat('order comment ', CAST(id AS STRING)) END AS o_comment
  FROM range(1500);

-- @setup
CREATE OR REPLACE TEMPORARY VIEW lineitem AS SELECT
  CAST(div(l.id, 4) + 1 AS INT) AS l_orderkey,
  CAST(pmod(l.id * 7, 200) + 1 AS INT) AS l_partkey,
  CAST(pmod(pmod(l.id * 7, 200) + pmod(l.id, 4) * 25, 100) + 1 AS INT) AS l_suppkey,
  CAST(pmod(l.id, 4) + 1 AS INT) AS l_linenumber, CAST(pmod(l.id, 50) + 1 AS DECIMAL(15,2)) AS l_quantity,
  CAST((pmod(l.id, 50) + 1) * (900 + pmod(pmod(l.id * 7, 200), 1000) / 10.0) AS DECIMAL(15,2)) AS l_extendedprice,
  CAST(pmod(l.id, 11) / 100.0 AS DECIMAL(15,2)) AS l_discount, CAST(pmod(l.id, 9) / 100.0 AS DECIMAL(15,2)) AS l_tax,
  CASE WHEN date_add(o.o_orderdate, CAST(pmod(l.id, 120) AS INT) + 31) <= DATE '1995-06-17' THEN element_at(array('R', 'A'), CAST(pmod(l.id, 2) AS INT) + 1) ELSE 'N' END AS l_returnflag,
  CASE WHEN date_add(o.o_orderdate, CAST(pmod(l.id, 120) AS INT) + 1) > DATE '1995-06-17' THEN 'O' ELSE 'F' END AS l_linestatus,
  date_add(o.o_orderdate, CAST(pmod(l.id, 120) AS INT) + 1) AS l_shipdate,
  date_add(o.o_orderdate, CAST(pmod(l.id * 3, 90) AS INT) + 30) AS l_commitdate,
  date_add(o.o_orderdate, CAST(pmod(l.id, 120) + pmod(l.id * 7, 30) AS INT) + 2) AS l_receiptdate,
  element_at(array('DELIVER IN PERSON', 'COLLECT COD', 'NONE', 'TAKE BACK RETURN'), CAST(pmod(l.id * 3, 4) AS INT) + 1) AS l_shipinstruct, element_at(array('REG AIR', 'AIR', 'RAIL', 'SHIP', 'TRUCK', 'MAIL', 'FOB'), CAST(pmod(l.id * 5, 7) AS INT) + 1) AS l_shipmode,
  concat('lineitem comment ', CAST(l.id AS STRING)) AS l_comment
  FROM range(6000) AS l JOIN orders AS o ON o.o_orderkey = div(l.id, 4) + 1;

-- TPC-H Q1
SELECT
    l_returnflag,
    l_linestatus,
    sum(l_quantity) AS sum_qty,
    sum(l_extendedprice) AS sum_base_price,
    sum(l_extendedprice * (1 - l_discount)) AS sum_disc_price,
    sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) AS sum_charge,
    avg(l_quantity) AS avg_qty,
    avg(l_extendedprice) AS avg_price,
    avg(l_discount) AS avg_disc,
    count(*) AS count_order
FROM
    lineitem
WHERE
    l_shipdate <= CAST('1998-09-02' AS date)
GROUP BY
    l_returnflag,
    l_linestatus
ORDER BY
    l_returnflag,
    l_linestatus;

-- TPC-H Q2
SELECT
    s_acctbal,
    s_name,
    n_name,
    p_partkey,
    p_mfgr,
    s_address,
    s_phone,
    s_comment
FROM
    part,
    supplier,
    partsupp,
    nation,
    region
WHERE
    p_partkey = ps_partkey
    AND s_suppkey = ps_suppkey
    AND p_size = 15
    AND p_type LIKE '%BRASS'
    AND s_nationkey = n_nationkey
    AND n_regionkey = r_regionkey
    AND r_name = 'EUROPE'
    AND ps_supplycost = (
        SELECT
            min(ps_supplycost)
        FROM
            partsupp,
            supplier,
            nation,
            region
        WHERE
            p_partkey = ps_partkey
            AND s_suppkey = ps_suppkey
            AND s_nationkey = n_nationkey
            AND n_regionkey = r_regionkey
            AND r_name = 'EUROPE')
ORDER BY
    s_acctbal DESC,
    n_name,
    s_name,
    p_partkey
LIMIT 100;

-- TPC-H Q3
SELECT
    l_orderkey,
    sum(l_extendedprice * (1 - l_discount)) AS revenue,
    o_orderdate,
    o_shippriority
FROM
    customer,
    orders,
    lineitem
WHERE
    c_mktsegment = 'BUILDING'
    AND c_custkey = o_custkey
    AND l_orderkey = o_orderkey
    AND o_orderdate < CAST('1995-03-15' AS date)
    AND l_shipdate > CAST('1995-03-15' AS date)
GROUP BY
    l_orderkey,
    o_orderdate,
    o_shippriority
ORDER BY
    revenue DESC,
    o_orderdate
LIMIT 10;

-- TPC-H Q4
SELECT
    o_orderpriority,
    count(*) AS order_count
FROM
    orders
WHERE
    o_orderdate >= CAST('1993-07-01' AS date)
    AND o_orderdate < CAST('1993-10-01' AS date)
    AND EXISTS (
        SELECT
            *
        FROM
            lineitem
        WHERE
            l_orderkey = o_orderkey
            AND l_commitdate < l_receiptdate)
GROUP BY
    o_orderpriority
ORDER BY
    o_orderpriority;

-- TPC-H Q5
SELECT
    n_name,
    sum(l_extendedprice * (1 - l_discount)) AS revenue
FROM
    customer,
    orders,
    lineitem,
    supplier,
    nation,
    region
WHERE
    c_custkey = o_custkey
    AND l_orderkey = o_orderkey
    AND l_suppkey = s_suppkey
    AND c_nationkey = s_nationkey
    AND s_nationkey = n_nationkey
    AND n_regionkey = r_regionkey
    AND r_name = 'ASIA'
    AND o_orderdate >= CAST('1994-01-01' AS date)
    AND o_orderdate < CAST('1995-01-01' AS date)
GROUP BY
    n_name
ORDER BY
    revenue DESC;

-- TPC-H Q6
SELECT
    sum(l_extendedprice * l_discount) AS revenue
FROM
    lineitem
WHERE
    l_shipdate >= CAST('1994-01-01' AS date)
    AND l_shipdate < CAST('1995-01-01' AS date)
    AND l_discount BETWEEN 0.05
    AND 0.07
    AND l_quantity < 24;

-- TPC-H Q7
SELECT
    supp_nation,
    cust_nation,
    l_year,
    sum(volume) AS revenue
FROM (
    SELECT
        n1.n_name AS supp_nation,
        n2.n_name AS cust_nation,
        extract(year FROM l_shipdate) AS l_year,
        l_extendedprice * (1 - l_discount) AS volume
    FROM
        supplier,
        lineitem,
        orders,
        customer,
        nation n1,
        nation n2
    WHERE
        s_suppkey = l_suppkey
        AND o_orderkey = l_orderkey
        AND c_custkey = o_custkey
        AND s_nationkey = n1.n_nationkey
        AND c_nationkey = n2.n_nationkey
        AND ((n1.n_name = 'FRANCE'
                AND n2.n_name = 'GERMANY')
            OR (n1.n_name = 'GERMANY'
                AND n2.n_name = 'FRANCE'))
        AND l_shipdate BETWEEN CAST('1995-01-01' AS date)
        AND CAST('1996-12-31' AS date)) AS shipping
GROUP BY
    supp_nation,
    cust_nation,
    l_year
ORDER BY
    supp_nation,
    cust_nation,
    l_year;

-- TPC-H Q8
SELECT
    o_year,
    sum(
        CASE WHEN nation = 'BRAZIL' THEN
            volume
        ELSE
            0
        END) / sum(volume) AS mkt_share
FROM (
    SELECT
        extract(year FROM o_orderdate) AS o_year,
        l_extendedprice * (1 - l_discount) AS volume,
        n2.n_name AS nation
    FROM
        part,
        supplier,
        lineitem,
        orders,
        customer,
        nation n1,
        nation n2,
        region
    WHERE
        p_partkey = l_partkey
        AND s_suppkey = l_suppkey
        AND l_orderkey = o_orderkey
        AND o_custkey = c_custkey
        AND c_nationkey = n1.n_nationkey
        AND n1.n_regionkey = r_regionkey
        AND r_name = 'AMERICA'
        AND s_nationkey = n2.n_nationkey
        AND o_orderdate BETWEEN CAST('1995-01-01' AS date)
        AND CAST('1996-12-31' AS date)
        AND p_type = 'ECONOMY ANODIZED STEEL') AS all_nations
GROUP BY
    o_year
ORDER BY
    o_year;

-- TPC-H Q9
SELECT
    nation,
    o_year,
    sum(amount) AS sum_profit
FROM (
    SELECT
        n_name AS nation,
        extract(year FROM o_orderdate) AS o_year,
        l_extendedprice * (1 - l_discount) - ps_supplycost * l_quantity AS amount
    FROM
        part,
        supplier,
        lineitem,
        partsupp,
        orders,
        nation
    WHERE
        s_suppkey = l_suppkey
        AND ps_suppkey = l_suppkey
        AND ps_partkey = l_partkey
        AND p_partkey = l_partkey
        AND o_orderkey = l_orderkey
        AND s_nationkey = n_nationkey
        AND p_name LIKE '%green%') AS profit
GROUP BY
    nation,
    o_year
ORDER BY
    nation,
    o_year DESC;

-- TPC-H Q10
SELECT
    c_custkey,
    c_name,
    sum(l_extendedprice * (1 - l_discount)) AS revenue,
    c_acctbal,
    n_name,
    c_address,
    c_phone,
    c_comment
FROM
    customer,
    orders,
    lineitem,
    nation
WHERE
    c_custkey = o_custkey
    AND l_orderkey = o_orderkey
    AND o_orderdate >= CAST('1993-10-01' AS date)
    AND o_orderdate < CAST('1994-01-01' AS date)
    AND l_returnflag = 'R'
    AND c_nationkey = n_nationkey
GROUP BY
    c_custkey,
    c_name,
    c_acctbal,
    c_phone,
    n_name,
    c_address,
    c_comment
ORDER BY
    revenue DESC, c_custkey
LIMIT 20;

-- TPC-H Q11
SELECT
    ps_partkey,
    sum(ps_supplycost * ps_availqty) AS value
FROM
    partsupp,
    supplier,
    nation
WHERE
    ps_suppkey = s_suppkey
    AND s_nationkey = n_nationkey
    AND n_name = 'GERMANY'
GROUP BY
    ps_partkey
HAVING
    sum(ps_supplycost * ps_availqty) > (
        SELECT
            sum(ps_supplycost * ps_availqty) * 0.0001000000
        FROM
            partsupp,
            supplier,
            nation
        WHERE
            ps_suppkey = s_suppkey
            AND s_nationkey = n_nationkey
            AND n_name = 'GERMANY')
ORDER BY
    value DESC;

-- TPC-H Q12
SELECT
    l_shipmode,
    sum(
        CASE WHEN o_orderpriority = '1-URGENT'
            OR o_orderpriority = '2-HIGH' THEN
            1
        ELSE
            0
        END) AS high_line_count,
    sum(
        CASE WHEN o_orderpriority <> '1-URGENT'
            AND o_orderpriority <> '2-HIGH' THEN
            1
        ELSE
            0
        END) AS low_line_count
FROM
    orders,
    lineitem
WHERE
    o_orderkey = l_orderkey
    AND l_shipmode IN ('MAIL', 'SHIP')
    AND l_commitdate < l_receiptdate
    AND l_shipdate < l_commitdate
    AND l_receiptdate >= CAST('1994-01-01' AS date)
    AND l_receiptdate < CAST('1995-01-01' AS date)
GROUP BY
    l_shipmode
ORDER BY
    l_shipmode;

-- TPC-H Q13
SELECT
    c_count,
    count(*) AS custdist
FROM (
    SELECT
        c_custkey,
        count(o_orderkey)
    FROM
        customer
    LEFT OUTER JOIN orders ON c_custkey = o_custkey
    AND o_comment NOT LIKE '%special%requests%'
GROUP BY
    c_custkey) AS c_orders (c_custkey,
        c_count)
GROUP BY
    c_count
ORDER BY
    custdist DESC,
    c_count DESC;

-- TPC-H Q14
SELECT
    100.00 * sum(
        CASE WHEN p_type LIKE 'PROMO%' THEN
            l_extendedprice * (1 - l_discount)
        ELSE
            0
        END) / sum(l_extendedprice * (1 - l_discount)) AS promo_revenue
FROM
    lineitem,
    part
WHERE
    l_partkey = p_partkey
    AND l_shipdate >= date '1995-09-01'
    AND l_shipdate < CAST('1995-10-01' AS date);

-- TPC-H Q15
WITH revenue AS (
    SELECT
        l_suppkey AS supplier_no,
        sum(l_extendedprice * (1 - l_discount)) AS total_revenue
    FROM
        lineitem
    WHERE
        l_shipdate >= CAST('1996-01-01' AS date)
      AND l_shipdate < CAST('1996-04-01' AS date)
    GROUP BY
        supplier_no
)
SELECT
    s_suppkey,
    s_name,
    s_address,
    s_phone,
    total_revenue
FROM
    supplier,
    revenue
WHERE
    s_suppkey = supplier_no
    AND total_revenue = (
        SELECT
            max(total_revenue)
        FROM revenue)
ORDER BY
    s_suppkey;

-- TPC-H Q16
SELECT
    p_brand,
    p_type,
    p_size,
    count(DISTINCT ps_suppkey) AS supplier_cnt
FROM
    partsupp,
    part
WHERE
    p_partkey = ps_partkey
    AND p_brand <> 'Brand#45'
    AND p_type NOT LIKE 'MEDIUM POLISHED%'
    AND p_size IN (49, 14, 23, 45, 19, 3, 36, 9)
    AND ps_suppkey NOT IN (
        SELECT
            s_suppkey
        FROM
            supplier
        WHERE
            s_comment LIKE '%Customer%Complaints%')
GROUP BY
    p_brand,
    p_type,
    p_size
ORDER BY
    supplier_cnt DESC,
    p_brand,
    p_type,
    p_size;

-- TPC-H Q17
SELECT
    sum(l_extendedprice) / 7.0 AS avg_yearly
FROM
    lineitem,
    part
WHERE
    p_partkey = l_partkey
    AND p_brand = 'Brand#23'
    AND p_container = 'MED BOX'
    AND l_quantity < (
        SELECT
            0.2 * avg(l_quantity)
        FROM
            lineitem
        WHERE
            l_partkey = p_partkey);

-- TPC-H Q18
SELECT
    c_name,
    c_custkey,
    o_orderkey,
    o_orderdate,
    o_totalprice,
    sum(l_quantity)
FROM
    customer,
    orders,
    lineitem
WHERE
    o_orderkey IN (
        SELECT
            l_orderkey
        FROM
            lineitem
        GROUP BY
            l_orderkey
        HAVING
            sum(l_quantity) > 300)
    AND c_custkey = o_custkey
    AND o_orderkey = l_orderkey
GROUP BY
    c_name,
    c_custkey,
    o_orderkey,
    o_orderdate,
    o_totalprice
ORDER BY
    o_totalprice DESC,
    o_orderdate
LIMIT 100;

-- TPC-H Q19
SELECT
    sum(l_extendedprice * (1 - l_discount)) AS revenue
FROM
    lineitem,
    part
WHERE (p_partkey = l_partkey
    AND p_brand = 'Brand#12'
    AND p_container IN ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')
    AND l_quantity >= 1
    AND l_quantity <= 1 + 10
    AND p_size BETWEEN 1 AND 5
    AND l_shipmode IN ('AIR', 'AIR REG')
    AND l_shipinstruct = 'DELIVER IN PERSON')
    OR (p_partkey = l_partkey
        AND p_brand = 'Brand#23'
        AND p_container IN ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')
        AND l_quantity >= 10
        AND l_quantity <= 10 + 10
        AND p_size BETWEEN 1 AND 10
        AND l_shipmode IN ('AIR', 'AIR REG')
        AND l_shipinstruct = 'DELIVER IN PERSON')
    OR (p_partkey = l_partkey
        AND p_brand = 'Brand#34'
        AND p_container IN ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')
        AND l_quantity >= 20
        AND l_quantity <= 20 + 10
        AND p_size BETWEEN 1 AND 15
        AND l_shipmode IN ('AIR', 'AIR REG')
        AND l_shipinstruct = 'DELIVER IN PERSON');

-- TPC-H Q20
SELECT
    s_name,
    s_address
FROM
    supplier,
    nation
WHERE
    s_suppkey IN (
        SELECT
            ps_suppkey
        FROM
            partsupp
        WHERE
            ps_partkey IN (
                SELECT
                    p_partkey
                FROM
                    part
                WHERE
                    p_name LIKE 'forest%')
                AND ps_availqty > (
                    SELECT
                        0.5 * sum(l_quantity)
                    FROM
                        lineitem
                    WHERE
                        l_partkey = ps_partkey
                        AND l_suppkey = ps_suppkey
                        AND l_shipdate >= CAST('1994-01-01' AS date)
                        AND l_shipdate < CAST('1995-01-01' AS date)))
            AND s_nationkey = n_nationkey
            AND n_name = 'CANADA'
        ORDER BY
            s_name;

-- TPC-H Q21
SELECT
    s_name,
    count(*) AS numwait
FROM
    supplier,
    lineitem l1,
    orders,
    nation
WHERE
    s_suppkey = l1.l_suppkey
    AND o_orderkey = l1.l_orderkey
    AND o_orderstatus = 'F'
    AND l1.l_receiptdate > l1.l_commitdate
    AND EXISTS (
        SELECT
            *
        FROM
            lineitem l2
        WHERE
            l2.l_orderkey = l1.l_orderkey
            AND l2.l_suppkey <> l1.l_suppkey)
    AND NOT EXISTS (
        SELECT
            *
        FROM
            lineitem l3
        WHERE
            l3.l_orderkey = l1.l_orderkey
            AND l3.l_suppkey <> l1.l_suppkey
            AND l3.l_receiptdate > l3.l_commitdate)
    AND s_nationkey = n_nationkey
    AND n_name = 'SAUDI ARABIA'
GROUP BY
    s_name
ORDER BY
    numwait DESC,
    s_name
LIMIT 100;

-- TPC-H Q22
SELECT
    cntrycode,
    count(*) AS numcust,
    sum(c_acctbal) AS totacctbal
FROM (
    SELECT
        substring(c_phone FROM 1 FOR 2) AS cntrycode,
        c_acctbal
    FROM
        customer
    WHERE
        substring(c_phone FROM 1 FOR 2) IN ('13', '31', '23', '29', '30', '18', '17')
        AND c_acctbal > (
            SELECT
                avg(c_acctbal)
            FROM
                customer
            WHERE
                c_acctbal > 0.00
                AND substring(c_phone FROM 1 FOR 2) IN ('13', '31', '23', '29', '30', '18', '17'))
            AND NOT EXISTS (
                SELECT
                    *
                FROM
                    orders
                WHERE
                    o_custkey = c_custkey)) AS custsale
GROUP BY
    cntrycode
ORDER BY
    cntrycode;
